const EmbeddedApps = {};

EmbeddedApps.parse = (embeddedApps) => {
  const slidoApp = EmbeddedApps.parseSlido(embeddedApps);
  let parsed = {};

  if (slidoApp) {
    parsed = {
      slidoApp: {
        appId: slidoApp.appId,
        instanceInfo: slidoApp.instanceInfo,
        state: slidoApp.state
      }
    };
  }

  return parsed;
};

EmbeddedApps.parseSlido = (embeddedApps) => {
  const slidoApp = embeddedApps.find((embeddedApp) => embeddedApp.appId === 'Y2lzY29zcGFyazovL3VzL0FQUExJQ0FUSU9OLzQxODc1MGQ0LTM3ZDctNGY2MC1hOWE3LWEwZTE1NDFhNjRkNg' && embeddedApp.state === 'RUNNING');

  return slidoApp;
};

EmbeddedApps.getEmbeddedApps = (oldEmbeddedApps, newEmbeddedApps) => {
  let previous = null;

  if (oldEmbeddedApps) {
    previous = oldEmbeddedApps;
  }
  const current = newEmbeddedApps && EmbeddedApps.parse(newEmbeddedApps);
  const updates = {};

  if (previous !== current) {
    updates.slidoChanged = true;
  }
  // if (current) {
  //   // stopped and started again pr first time getting started
  //   if (previous && previous.slidoApp?.state === 'STOPPED' && current.slidoApp?.state === 'RUNNING' || !previous?.slidoApp && current.slidoApp?.state === 'RUNNING') {
  //     updates.slidoChanged = true;
  //   }

  //   // started to stopped
  //   if (previous && previous.slidoApp?.state === 'RUNNING' && current.slidoApp?.state === 'STOPPED') {
  //     updates.slidoChanged = true;
  //   }
  // }

  return {
    previous,
    current,
    updates
  };
};

export default EmbeddedApps;
